#include <stdio.h>

int func(int x, int y) {   /* ② 3과 5를 x, y가 받는다 */
    int sum = x + y;       /* ③ sum = 8 */
    return sum;            /* ④ 8을 돌려준다 */
}

main() {
    int r = func(3, 5);    /* ① 호출  ⑤ r = 8 */
    printf("%d", r);       /* ⑥ 8 출력 */
}

int  b = 10;
int *a = &b;   /* a는 b의 주소를 담는다 */
int  c = *a;   /* c는 a가 가리키는 곳의 값 = 10 */

*a = 20;       /* a가 가리키는 곳(= b)을 20으로 */
printf("%d", b);

int i, sum = 0;
for (i = 0; i <= 10; i++) {
    if (i % 2 != 0) continue;   /* 홀수는 건너뜀 */
    sum += i;                   /* 0+2+4+6+8+10 = 30 */
}
printf("%d", i + sum);          /* i는 11, sum은 30 */
